#!/usr/bin/env python3
"""Validate provenance and regenerate the Paper.js file-by-file navigation."""
import argparse
import hashlib
import json
from pathlib import Path
import re

BASE = Path(__file__).resolve().parent
ROOT = BASE.parents[1]


def tests(path):
    return re.findall(r'^pub fn (\w+_test)\(', (ROOT / path).read_text(), re.M)


def render(catalog):
    inventory = json.loads((BASE / 'inventory.json').read_text())['files']
    result = {}
    index = ['# Paper.js audit by upstream file', '',
             'Generated by `python3 scripts/paperjs/catalog.py` from `catalog.json`.', '',
             f"Pinned source: `{catalog['revision']}`. Extraction runtime: `{catalog['extraction_runtime']}`.",
             'Exact download dates were not recorded; the complete 37-file archive was consolidated on 2026-10-14.',
             'Counts below are our executable test functions, not upstream assertion coverage percentages.', '',
             '| Original file | Category | Fast | Slow |', '| --- | --- | ---: | ---: |']
    for entry in catalog['files']:
        name = entry['file']
        counts = {p: sum(len(tests(path)) for path in entry[p]) for p in ['fast', 'slow']}
        index.append(f"| [{name}](files/{name}.md) | {entry['category']} | {counts['fast']} | {counts['slow']} |")
        lines = [f'# {name}', '', '[Audit index](../INDEX.md) · [Archive](../upstream/' + name + ')', '',
                 f"Original path: `{entry['original_path']}`.",
                 f"Pinned revision: `{catalog['revision']}`; extraction runtime: `{catalog['extraction_runtime']}`.",
                 f"SHA-256: `{entry['sha256']}`.",
                 'Download date: not recorded. Archive consolidated: 2026-10-14.', '',
                 '## Scope', '', entry['disposition'], '', entry['review_scope'] + '.', '',
                 'This file-level disposition is not a claim that every assertion was executed or passed.', '']
        for profile in ['fast', 'slow']:
            lines += [f'## {profile.title()} release adaptations', '']
            if not entry[profile]:
                lines += ['None.', '']
            for path in entry[profile]:
                lines += [f'[{Path(path).name}](../../../{path})', '']
                lines += [f'- `{fn}`' for fn in tests(path)]
                lines += ['']
        for key, title in [('support', 'Shared adaptation helpers'), ('native_regressions', 'Native regressions with related provenance'), ('diagnostic_probes', 'Diagnostic probes (not release tests)'), ('diagnostic_assets', 'Raw comparison drivers (not release tests)')]:
            lines += [f'## {title}', '']
            lines += [f'- [{Path(path).name}](../../../{path})' for path in entry[key]] or ['None.']
            lines += ['']
        lines += ['## Evidence and extracted fixtures', '']
        lines += [f'- [{name}](../{name})' for name in entry['evidence'] + entry['fixtures']] or ['See [file screening](../final-file-screening.json).']
        if name in inventory:
            lines += ['', '## Original test blocks', '',
                      'Original titles and historical block dispositions from `inventory.json`.',
                      'Consult the evidence above and the current README for subsequent fixes; these are not live pass/fail results.', '']
            for i, block in enumerate(inventory[name]['test_blocks']):
                lines.append(f"- Block {i}: `{block['title_expression']}` — {block.get('status', 'inventoried')}")
        else:
            lines += ['', 'Original declarations and screening scope are recorded in [final-file-screening.json](../final-file-screening.json).']
        result[BASE / 'files' / (name + '.md')] = '\n'.join(lines) + '\n'
    index += ['', 'Native regressions remain organized by our API contract. They are linked from the originating file pages,',
              'but are not counted as upstream assertion parity. Diagnostic probes can retain expected API differences.', '']
    result[BASE / 'INDEX.md'] = '\n'.join(index)
    return result


def validate(catalog):
    registered = set()
    for entry in catalog['files']:
        source = BASE / 'upstream' / entry['file']
        assert hashlib.sha256(source.read_bytes()).hexdigest() == entry['sha256'], source
        for key in ['fast', 'slow', 'support', 'native_regressions', 'diagnostic_probes', 'diagnostic_assets']:
            for path in entry[key]:
                assert (ROOT / path).is_file(), path
        for key in ['evidence', 'fixtures']:
            for path in entry[key]:
                assert (BASE / path).is_file(), path
        for profile in ['fast', 'slow']:
            registry_name = 'modules.txt' if profile == 'fast' else 'slow-modules.txt'
            registry = (ROOT / 'test_portable' / registry_name).read_text().splitlines()
            for path in entry[profile]:
                assert path not in registered, ('duplicate adaptation', path)
                registered.add(path)
                assert Path(path).name in registry, ('not in portable selection', path)
    discovered = {str(p.relative_to(ROOT)) for directory in ['test', 'test_slow'] for p in (ROOT / directory).glob('svg_path_paper_*_test.gleam')}
    assert registered == discovered, ('unindexed or missing adaptations', registered ^ discovered)
    probes = {p for e in catalog['files'] for p in e['diagnostic_probes']}
    discovered_probes = {str(p.relative_to(ROOT)) for p in (ROOT / 'test_paperjs/src').glob('paper_*.gleam')}
    assert probes == discovered_probes, ('unindexed or missing probes', probes ^ discovered_probes)
    archived = {p.name for p in (BASE / 'upstream').glob('*.js')}
    assert archived == {e['file'] for e in catalog['files']}, 'Archive/catalog mismatch'
    screening = json.loads((BASE / 'final-file-screening.json').read_text())
    assert {e['file']: e['sha256'] for e in screening['files']} == {e['file']: e['sha256'] for e in catalog['files']}


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--check', action='store_true')
    args = parser.parse_args()
    catalog = json.loads((BASE / 'catalog.json').read_text())
    validate(catalog)
    for path, content in render(catalog).items():
        if args.check:
            assert path.exists() and path.read_text() == content, f'Stale index: {path}; run {__file__}'
        else:
            path.parent.mkdir(parents=True, exist_ok=True)
            path.write_text(content)
    print(f"Verified {len(catalog['files'])} upstream files and all Paper.js adaptation modules.")


if __name__ == '__main__':
    main()
